{"command":"create","path":"/workspace/codebase/rust/src/args.rs","file_text":"use serde_json::{Map, Number, Value};
use std::path::PathBuf;

pub const DEFAULT_EXTENSIONS: &str = "cjs,es,es6,js,jsx,mjs,ts,tsx";

#[derive(Debug, Clone)]
pub struct Options {
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: u8,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: String,
    pub ignore_patterns: Vec<String>,
    pub ignore_configs: Vec<PathBuf>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<Value>,
    pub fail_on_error: bool,
    pub stdin: bool,
    pub values: Map<String, Value>,
}

#[derive(Debug)]
pub enum ParseResult {
    Run { options: Options, paths: Vec<String> },
    Exit { code: i32, message: String },
}

fn is_option(value: Option<&String>) -> bool {
    value.is_some_and(|value| value.starts_with('-'))
}

fn parse_value(value: &str) -> Value {
    serde_json::from_str(value).unwrap_or_else(|_| Value::String(value.to_owned()))
}

fn option_value(args: &[String], index: &mut usize, inline: Option<String>, name: &str) -> Result<String, String> {
    if let Some(value) = inline { return Ok(value); }
    if *index + 1 < args.len() && !is_option(args.get(*index + 1)) {
        *index += 1;
        return Ok(args[*index].clone());
    }
    Err(format!("Missing value: --{name} requires a value\n\n---\n\n{}", help_text()))
}

fn set(map: &mut Map<String, Value>, key: &str, value: Value) {
    map.insert(key.to_owned(), value);
}

pub fn parse(args: &[String]) -> ParseResult {
    let mut options = Options {
        transform: "./transform.js".into(), cpus: None, verbose: 0, dry: false,
        print: false, babel: true, extensions: DEFAULT_EXTENSIONS.into(),
        ignore_patterns: Vec::new(), ignore_configs: Vec::new(), gitignore: false,
        run_in_band: false, silent: false, parser: "babel".into(), parser_config: None,
        fail_on_error: false, stdin: false, values: Map::new(),
    };
    set(&mut options.values, "transform", Value::String(options.transform.clone()));
    set(&mut options.values, "verbose", Value::from(0));
    set(&mut options.values, "dry", Value::Bool(false));
    set(&mut options.values, "print", Value::Bool(false));
    set(&mut options.values, "babel", Value::Bool(true));
    set(&mut options.values, "extensions", Value::String(options.extensions.clone()));
    set(&mut options.values, "ignorePattern", Value::Array(vec![]));
    set(&mut options.values, "ignoreConfig", Value::Array(vec![]));
    set(&mut options.values, "gitignore", Value::Bool(false));
    set(&mut options.values, "runInBand", Value::Bool(false));
    set(&mut options.values, "silent", Value::Bool(false));
    set(&mut options.values, "parser", Value::String(options.parser.clone()));
    set(&mut options.values, "failOnError", Value::Bool(false));
    set(&mut options.values, "stdin", Value::Bool(false));

    let mut paths = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if !arg.starts_with('-') {
            paths.push(arg.clone());
            i += 1;
            continue;
        }
        let (name, inline) = arg.split_once('=').map_or((arg.as_str(), None), |(name, value)| (name, Some(value.to_owned())));
        if matches!(name, "--help" | "-h") {
            return ParseResult::Exit { code: 0, message: help_text() };
        }
        if name == "--version" {
            return ParseResult::Exit { code: 0, message: crate::package::version_text() };
        }

        let result: Result<(), String> = (|| {
            match name {
                "--transform" | "-t" => {
                    let value = option_value(args, &mut i, inline, "transform")?;
                    options.transform = value.clone(); set(&mut options.values, "transform", Value::String(value));
                }
                "--cpus" | "-c" => {
                    let value = option_value(args, &mut i, inline, "cpus")?;
                    options.cpus = value.parse().ok();
                    set(&mut options.values, "cpus", options.cpus.map_or(Value::Null, |n| Value::from(n as u64)));
                }
                "--verbose" | "-v" => {
                    let value = option_value(args, &mut i, inline, "verbose")?;
                    options.verbose = value.parse().unwrap_or(u8::MAX);
                    set(&mut options.values, "verbose", Value::from(options.verbose));
                }
                "--extensions" => {
                    let value = option_value(args, &mut i, inline, "extensions")?;
                    options.extensions = value.clone(); set(&mut options.values, "extensions", Value::String(value));
                }
                "--parser" => {
                    let value = option_value(args, &mut i, inline, "parser")?;
                    options.parser = value.clone(); set(&mut options.values, "parser", Value::String(value));
                }
                "--parser-config" => {
                    let value = option_value(args, &mut i, inline, "parser-config")?;
                    let text = std::fs::read_to_string(&value).map_err(|error| error.to_string())?;
                    let config = serde_json::from_str(&text).map_err(|error| error.to_string())?;
                    options.parser_config = Some(config.clone()); set(&mut options.values, "parserConfig", config);
                }
                "--ignore-pattern" => {
                    let value = option_value(args, &mut i, inline, "ignore-pattern")?;
                    options.ignore_patterns.push(value.clone());
                    set(&mut options.values, "ignorePattern", Value::Array(options.ignore_patterns.iter().cloned().map(Value::String).collect()));
                }
                "--ignore-config" => {
                    let value = option_value(args, &mut i, inline, "ignore-config")?;
                    options.ignore_configs.push(PathBuf::from(&value));
                    set(&mut options.values, "ignoreConfig", Value::Array(options.ignore_configs.iter().map(|p| Value::String(p.to_string_lossy().into())).collect()));
                }
                "--dry" | "-d" | "--no-dry" | "--print" | "-p" | "--no-print" |
                "--babel" | "--no-babel" | "--gitignore" | "--no-gitignore" |
                "--run-in-band" | "--no-run-in-band" | "--silent" | "-s" | "--no-silent" |
                "--fail-on-error" | "--no-fail-on-error" | "--stdin" | "--no-stdin" => {
                    let enabled = inline.as_deref().map_or(!name.starts_with("--no-"), |v| v == "1");
                    let key = match name.trim_start_matches("--no-").trim_start_matches("--") {
                        "d" => "dry", "p" => "print", "s" => "silent", other => other,
                    };
                    match key {
                        "dry" => options.dry = enabled,
                        "print" => options.print = enabled,
                        "babel" => options.babel = enabled,
                        "gitignore" => options.gitignore = enabled,
                        "run-in-band" => options.run_in_band = enabled,
                        "silent" => options.silent = enabled,
                        "fail-on-error" => options.fail_on_error = enabled,
                        "stdin" => options.stdin = enabled,
                        _ => unreachable!(),
                    }
                    let json_key = match key { "run-in-band" => "runInBand", "fail-on-error" => "failOnError", other => other };
                    set(&mut options.values, json_key, Value::Bool(enabled));
                }
                _ => {
                    let key = name.trim_start_matches('-').strip_prefix("no-").unwrap_or(name.trim_start_matches('-'));
                    let had_value = options.values.contains_key(key) && options.values[key] != Value::Bool(true);
                    let value = if let Some(value) = inline {
                        parse_value(&value)
                    } else if i + 1 < args.len() && !is_option(args.get(i + 1)) {
                        i += 1; parse_value(&args[i])
                    } else {
                        Value::Bool(true)
                    };
                    if had_value {
                        let old = options.values.remove(key).unwrap();
                        let mut values = match old { Value::Array(values) => values, Value::Bool(true) => vec![], value => vec![value] };
                        values.push(value); set(&mut options.values, key, Value::Array(values));
                    } else { set(&mut options.values, key, value); }
                }
            }
            Ok(())
        })();
        if let Err(message) = result { return ParseResult::Exit { code: 1, message }; }
        i += 1;
    }

    if !["babel", "babylon", "flow", "ts", "tsx"].contains(&options.parser.as_str()) {
        return ParseResult::Exit { code: 1, message: format!("Error: --parser must be one of the values babel,babylon,flow,ts,tsx\n\n---\n\n{}", help_text()) };
    }
    if ![0, 1, 2].contains(&options.verbose) {
        return ParseResult::Exit { code: 1, message: format!("Error: --verbose must be one of the values 0,1,2\n\n---\n\n{}", help_text()) };
    }
    if paths.is_empty() && !options.stdin {
        return ParseResult::Exit { code: 1, message: format!("Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}", help_text()) };
    }
    ParseResult::Run { options, paths }
}

pub fn help_text() -> String {
    format!("Usage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n      --(no-)babel             apply babeljs to the transform file\n                                (default: true)\n  -c, --cpus=N                 start at most N child processes to process source files\n                                (default: max(all - 1, 1))\n  -d, --(no-)dry               dry run (no changes are made to files)\n                                (default: false)\n      --extensions=EXT         transform files with these file extensions (comma separated list)\n                                (default: {DEFAULT_EXTENSIONS})\n      --(no-)fail-on-error     Return a non-zero code when there are errors\n                                (default: false)\n  -h, --help                   print this help and exit\n      --ignore-config=FILE ... ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)\n      --ignore-pattern=GLOB ...ignore files that match a provided glob expression\n      --(no-)gitignore         adds entries the current directory's .gitignore file\n                                (default: false)\n      --parser=babel|babylon|flow|ts|tsx  the parser to use for parsing the source files\n                                (default: babel)\n      --parser-config=FILE     path to a JSON file containing a custom parser configuration for flow or babylon\n  -p, --(no-)print             print transformed files to stdout, useful for development\n                                (default: false)\n      --(no-)run-in-band       run serially in the current process\n                                (default: false)\n  -s, --(no-)silent            do not write to stdout or stderr\n                                (default: false)\n      --(no-)stdin             read file/directory list from stdin\n                                (default: false)\n  -t, --transform=FILE         path to the transform file. Can be either a local path or url\n                                (default: ./transform.js)\n  -v, --verbose=0|1|2         show more information about the transform process\n                                (default: 0)\n      --version                print version and exit\n")
}

