{"command":"create","path":"/workspace/codebase/rust/src/package.rs","file_text":"use serde_json::Value;
use std::path::{Path, PathBuf};

pub fn package_root() -> PathBuf {
    if let Some(root) = std::env::var_os("JSCODESHIFT_ROOT") { return root.into(); }
    if let Ok(exe) = std::env::current_exe() {
        for ancestor in exe.ancestors() {
            if ancestor.join("package.json").is_file() { return ancestor.to_path_buf(); }
        }
    }
    std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn version_at(path: &Path) -> Option<String> {
    let package: Value = serde_json::from_str(&std::fs::read_to_string(path).ok()?).ok()?;
    package.get("version")?.as_str().map(ToOwned::to_owned)
}

pub fn dependency_version(name: &str) -> String {
    let root = package_root();
    let direct = root.join("node_modules").join(name).join("package.json");
    if let Some(version) = version_at(&direct) { return version; }
    "unknown".into()
}

pub fn version_text() -> String {
    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n\n",
        env!("CARGO_PKG_VERSION"),
        dependency_version("@babel/core"),
        dependency_version("@babel/parser"),
        dependency_version("flow-parser"),
        dependency_version("recast"),
    )
}
