{"command":"create","path":"/workspace/codebase/rust/src/ignore.rs","file_text":"use globset::{GlobBuilder, GlobMatcher};
use std::path::{Path, PathBuf};

pub struct IgnoreRules {
    patterns: Vec<String>,
    matchers: Vec<GlobMatcher>,
}

impl IgnoreRules {
    pub fn new() -> Self { Self { patterns: Vec::new(), matchers: Vec::new() } }

    pub fn add(&mut self, value: &str) {
        let value = value.trim_end_matches('\r');
        if value.is_empty() || value.starts_with('#') { return; }
        if !value.contains('/') && !value.contains('\\') {
            self.push(format!("**/{value}"));
        } else if value.ends_with('/') || value.ends_with('\\') {
            self.push(format!("**/{value}**"));
            self.push(format!("{value}**"));
        }
        self.push(value.to_owned());
    }

    fn push(&mut self, pattern: String) {
        let normalized = pattern.replace('\\', "/");
        let glob = GlobBuilder::new(&normalized).literal_separator(false).backslash_escape(false).build();
        if let Ok(glob) = glob {
            self.patterns.push(normalized);
            self.matchers.push(glob.compile_matcher());
        }
    }

    pub fn add_file(&mut self, path: &Path) -> std::io::Result<()> {
        for line in std::fs::read_to_string(path)?.lines() { self.add(line); }
        Ok(())
    }

    pub fn is_ignored(&self, path: &Path) -> bool {
        if self.matchers.is_empty() { return false; }
        let path = path.to_string_lossy().replace('\\', "/");
        let normalized = strip_traversal(&path);
        self.matchers.iter().any(|matcher| matcher.is_match(&path) || matcher.is_match(normalized))
    }
}

fn strip_traversal(path: &str) -> &str {
    let mut value = path;
    while let Some(rest) = value.strip_prefix("./").or_else(|| value.strip_prefix("../")) { value = rest; }
    value
}

pub fn discover(paths: &[String], extensions: &[String], ignores: &IgnoreRules) -> Vec<PathBuf> {
    let mut result = Vec::new();
    for input in paths {
        let path = PathBuf::from(input);
        match std::fs::symlink_metadata(&path) {
            Ok(metadata) if metadata.is_dir() => visit_directory(&path, extensions, ignores, &mut result),
            Ok(_) if selected(&path, extensions) && !ignores.is_ignored(&path) => result.push(path),
            Ok(_) => {}
            Err(_) => eprintln!("Skipping path {input} which does not exist. "),
        }
    }
    result
}

fn visit_directory(directory: &Path, extensions: &[String], ignores: &IgnoreRules, result: &mut Vec<PathBuf>) {
    let entries = match std::fs::read_dir(directory) { Ok(entries) => entries, Err(error) => panic!("{error}") };
    for entry in entries {
        let entry = match entry { Ok(entry) => entry, Err(_) => continue };
        let path = entry.path();
        let metadata = match std::fs::metadata(&path) {
            Ok(metadata) => metadata,
            Err(_) => { println!("Skipping path \"{}\" which does not exist.", path.display()); continue; }
        };
        if ignores.is_ignored(&path) { continue; }
        if metadata.is_dir() { visit_directory(&path, extensions, ignores, result); }
        else if selected(&path, extensions) { result.push(path); }
    }
}

fn selected(path: &Path, extensions: &[String]) -> bool {
    extensions.is_empty() || path.extension().is_some_and(|extension| {
