'use strict';

const readline = require('readline');
const {DEFAULT_EXTENSIONS} = require('@babel/core');
const getParser = require('./getParser');
const core = require('./core');

const PREFIX = '\x1ejscodeshift:';
let transform;
let parserFromTransform;

function setup(transformPath, useBabel) {
  if (useBabel === 'babel') {
    let presetEnv;
    try { presetEnv = require('@babel/preset-env'); } catch (_) {}
    const presets = [];
    if (presetEnv) presets.push([presetEnv.default, {targets: {node: true}}]);
    presets.push(/\.tsx?$/.test(transformPath) ?
      require('@babel/preset-typescript').default :
      require('@babel/preset-flow').default);
    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [/@babel\/parser/, /\/flow-parser\//, /\/recast\//, /\/ast-types\//],
    });
  }
  const loaded = require(transformPath);
  transform = typeof loaded.default === 'function' ? loaded.default : loaded;
  if (loaded.parser) {
    parserFromTransform = typeof loaded.parser === 'string' ? getParser(loaded.parser) : loaded.parser;
  }
  if (typeof transform !== 'function') throw new TypeError('Transform file must export a function');
}

function trimStackTrace(trace) {
  if (!trace) return '';
  const result = [];
  for (const line of trace.split('\n')) {
    if (line.includes(__filename)) break;
    result.push(line);
  }
  return result.join('\n');
}

async function execute(request) {
  const reports = [];
  const stats = {};
  const options = request.options || {};
  const parser = parserFromTransform || getParser(options.parser, options.parserConfig);
  const jscodeshift = core.withParser(parser);
  const api = {
    j: jscodeshift,
    jscodeshift,
    stats(name, quantity) {
      if (!options.dry) return;
      quantity = typeof quantity === 'number' ? quantity : 1;
      stats[name] = (stats[name] || 0) + quantity;
    },
    report(message) { reports.push(String(message)); },
  };
  try {
    const output = await transform(
      {path: request.path, source: request.source},
      api,
      options
    );
    const status = !output ? 'skip' : output === request.source ? 'nochange' : 'ok';
    return {id: request.id, status, output: status === 'ok' ? output : null, reports, stats};
  } catch (error) {
    const message = error && error.message ? String(error.message) : String(error);
    return {
      id: request.id,
      status: 'error',
      error: `Transformation error (${message.replace(/\n/g, ' ')})\n${trimStackTrace(error && error.stack)}`,
      reports,
      stats,
    };
  }
}

setup(process.argv[2], process.argv[3]);
const input = readline.createInterface({input: process.stdin, crlfDelay: Infinity});
let queue = Promise.resolve();
input.on('line', line => {
  queue = queue.then(async () => {
    const response = await execute(JSON.parse(line));
    process.stdout.write(PREFIX + JSON.stringify(response) + '\n');
  });
});
