{"command":"create","path":"/workspace/codebase/rust/src/runner.rs","file_text":"use crate::args::Options;
use crate::protocol::{Request, Response, PREFIX};
use serde::Serialize;
use serde_json::{Map, Value};
use std::collections::BTreeMap;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::sync::{mpsc, Arc};
use std::thread;
use std::time::Instant;

#[derive(Default, Debug, Serialize)]
pub struct RunResult {
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
    pub stats: BTreeMap<String, Value>,
    #[serde(rename = "timeElapsed")]
    pub time_elapsed: String,
}

struct Completed {
    path: PathBuf,
    response: Response,
    source: String,
}

struct Host {
    child: Child,
    input: ChildStdin,
    output: BufReader<ChildStdout>,
}

impl Host {
    fn start(transform: &Path, babel: bool) -> Result<Self, String> {
        let root = crate::package::package_root();
        let mut child = Command::new("node")
            .arg(root.join("bridge/transform-host.js"))
            .arg(transform)
            .arg(if babel { "babel" } else { "no-babel" })
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .env("JSCODESHIFT_ROOT", &root)
            .spawn()
            .map_err(|error| format!("Unable to start transform host: {error}"))?;
        let input = child.stdin.take().ok_or("Unable to open transform host input")?;
        let output = BufReader::new(child.stdout.take().ok_or("Unable to open transform host output")?);
        Ok(Self { child, input, output })
    }

    fn execute(&mut self, id: usize, path: &Path, source: &str, options: &Map<String, Value>) -> Result<Response, String> {
        let path_text = path.to_string_lossy();
        serde_json::to_writer(&mut self.input, &Request { id, path: &path_text, source, options })
            .map_err(|error| error.to_string())?;
        self.input.write_all(b"\n").and_then(|_| self.input.flush()).map_err(|error| error.to_string())?;
        loop {
            let mut line = String::new();
            let count = self.output.read_line(&mut line).map_err(|error| error.to_string())?;
            if count == 0 { return Err("Transform host exited before returning a result".into()); }
            if let Some(index) = line.find(PREFIX) {
                print!("{}", &line[..index]);
                let payload = line[index + PREFIX.len()..].trim_end();
                return serde_json::from_str(payload).map_err(|error| format!("Invalid transform host response: {error}"));
            }
            print!("{line}");
        }
    }
}

impl Drop for Host {
    fn drop(&mut self) {
        drop(self.input.flush());
        let _ = self.child.wait();
    }
}

pub fn run(transform: &Path, files: Vec<PathBuf>, options: Options) -> RunResult {
    let started = Instant::now();
    let mut result = RunResult::default();
    if files.is_empty() {
        println!("No files selected, nothing to do. ");
        return result;
    }

    let available = thread::available_parallelism().map_or(1, usize::from).saturating_sub(1).max(1);
    let process_count = if options.run_in_band { 1 } else { files.len().min(options.cpus.unwrap_or(available).min(available).max(1)) };
    let chunk_size = if process_count > 1 { files.len().div_ceil(process_count).min(50) } else { files.len() };
    if !options.silent {
        println!("Processing {} files... ", files.len());
        if !options.run_in_band { println!("Spawning {process_count} workers..."); }
        if options.dry { println!("Running in dry mode, no files will be written! "); }
    }

    let transform = Arc::new(transform.to_path_buf());
    let options = Arc::new(options);
    let (sender, receiver) = mpsc::channel();
    let chunks: Vec<_> = files.chunks(chunk_size).map(|chunk| chunk.to_vec()).collect();
    let mut assignments = vec![Vec::new(); process_count];
    for (index, chunk) in chunks.into_iter().enumerate() { assignments[index % process_count].extend(chunk); }

    for (worker_index, paths) in assignments.into_iter().enumerate() {
        let sender = sender.clone();
        let transform = Arc::clone(&transform);
        let options = Arc::clone(&options);
        thread::spawn(move || {
            let mut host = match Host::start(&transform, options.babel) {
                Ok(host) => host,
                Err(error) => {
                    for (offset, path) in paths.into_iter().enumerate() {
                        let _ = sender.send(Completed { path, source: String::new(), response: error_response(worker_index * 1_000_000 + offset, &error) });
                    }
                    return;
                }
            };
            for (offset, path) in paths.into_iter().enumerate() {
                let id = worker_index * 1_000_000 + offset;
                let source = match fs::read_to_string(&path) {
                    Ok(source) => source,
                    Err(error) => {
                        let _ = sender.send(Completed { path, source: String::new(), response: error_response(id, &format!("File error: {error}")) });
                        continue;
                    }
                };
                let response = host.execute(id, &path, &source, &options.values)
                    .unwrap_or_else(|error| error_response(id, &error));
                let _ = sender.send(Completed { path, response, source });
            }
        });
    }
    drop(sender);

    for completed in receiver {
        consume(completed, &options, &mut result);
    }
    result.time_elapsed = format!("{:.3}", started.elapsed().as_secs_f64());
    if !options.silent {
        println!("All done. ");
        println!("Results: ");
        println!("{} errors", result.error);
        println!("{} unmodified", result.nochange);
        println!("{} skipped", result.skip);
        println!("{} ok", result.ok);
        if !result.stats.is_empty() {
            println!("Stats: ");
            for (name, quantity) in &result.stats { println!("{name}: {}", display_value(quantity)); }
        }
        println!("Time elapsed: {}seconds ", result.time_elapsed);
    }
    result
}

fn consume(completed: Completed, options: &Options, result: &mut RunResult) {
    let path = completed.path.to_string_lossy();
    for report in completed.response.reports { println!(" REP {path} {report}"); }
    for (name, quantity) in completed.response.stats {
        let current = result.stats.entry(name).or_insert(Value::from(0));
        *current = add_numbers(current, &quantity);
    }
    let message = completed.response.error.as_deref().map_or_else(|| path.to_string(), |error| format!("{path} {error}"));
    match completed.response.status.as_str() {
        "ok" => {
            if let Some(output) = completed.response.output {
                if options.print { println!("{output}"); }
                if !options.dry {
                    if let Err(error) = atomic_write(&completed.path, output.as_bytes()) {
                        result.error += 1;
                        eprintln!(" ERR {path} File writer error: {error}");
                        return;
                    }
                }
            }
            result.ok += 1;
            if options.verbose >= 2 { println!(" OKK {message}"); }
        }
        "nochange" => { result.nochange += 1; if options.verbose >= 1 { println!(" NOC {message}"); } }
        "skip" => { result.skip += 1; if options.verbose >= 1 { println!(" SKIP {message}"); } }
        _ => { result.error += 1; eprintln!(" ERR {message}"); }
    }
    let _ = completed.response.id;
    let _ = completed.source;
}

fn atomic_write(path: &Path, contents: &[u8]) -> std::io::Result<()> {
    let file_name = path.file_name().and_then(|name| name.to_str()).unwrap_or("jscodeshift");
    let temporary = path.with_file_name(format!(".{file_name}.{}.tmp", std::process::id()));
    fs::write(&temporary, contents)?;
    if let Ok(metadata) = fs::metadata(path) { fs::set_permissions(&temporary, metadata.permissions())?; }
    match fs::rename(&temporary, path) {
        Ok(()) => Ok(()),
        Err(error) => { let _ = fs::remove_file(&temporary); Err(error) }
    }
}

fn error_response(id: usize, error: &str) -> Response {
    Response { id, status: "error".into(), output: None, error: Some(error.into()), reports: vec![], stats: Map::new() }
}

fn add_numbers(left: &Value, right: &Value) -> Value {
    match (left.as_i64(), right.as_i64()) {
        (Some(left), Some(right)) => Value::from(left + right),
        _ => Value::from(left.as_f64().unwrap_or(0.0) + right.as_f64().unwrap_or(0.0)),
    }
}

fn display_value(value: &Value) -> String {
    value.as_str().map(ToOwned::to_owned).unwrap_or_else(|| value.to_string())
}

pub fn download_transform(url: &str) -> Result<PathBuf, String> {
    let extension = Path::new(url).extension().and_then(|value| value.to_str()).unwrap_or("js");
    let path = std::env::temp_dir().join(format!("jscodeshift-{}.{}", std::process::id(), extension));
    let status = Command::new("curl").args(["-L", "--fail", "--silent", "--show-error", "-o"]).arg(&path).arg(url)
        .status().map_err(|error| format!("Unable to download transform: {error}"))?;
    if status.success() { Ok(path) } else { Err(format!("Unable to download transform from {url}")) }
}
