    }
    let extensions = options.extensions.split(',').map(ToOwned::to_owned).collect::<Vec<_>>();
    let files = discover(&paths, &extensions, &ignores);

    let (transform, downloaded) = if options.transform.starts_with("http://") || options.transform.starts_with("https://") {
