        }
    } else {
        let path = PathBuf::from(&options.transform);
        let path = if path.is_absolute() { path } else { std::env::current_dir().unwrap().join(path) };
        (path, false)
    };
    if !transform.exists() {
        eprintln!("ERROR Transform file {} does not exist ", transform.display());
        return;
    }

    let fail_on_error = options.fail_on_error;
    let silent = options.silent;
    let result = runner::run(&transform, files, options);
    if downloaded { let _ = std::fs::remove_file(transform); }
    if let Some(path) = std::env::var_os("JSCODESHIFT_RESULT_FILE") {
        if let Ok(output) = serde_json::to_vec(&result) { let _ = std::fs::write(path, output); }
