const {spawn} = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

function binary(root) {
  const name = process.platform === 'win32' ? 'jscodeshift.exe' : 'jscodeshift';
  for (const profile of ['release', 'debug']) {
    const candidate = path.join(root, 'target', profile, name);
    if (fs.existsSync(candidate)) return {command: candidate, prefix: []};
  }
  return {command: 'cargo', prefix: ['run', '--quiet', '--manifest-path', path.join(root, 'Cargo.toml'), '--']};
}

function optionArgs(options) {
  const known = new Set(['transform', 'cpus', 'verbose', 'dry', 'print', 'babel', 'extensions', 'ignorePattern', 'ignoreConfig', 'gitignore', 'runInBand', 'silent', 'parser', 'parserConfig', 'failOnError', 'stdin', 'ignoreSet']);
  const result = [];
  const value = (name, current) => current != null && result.push(`--${name}=${current}`);
  value('cpus', options.cpus);
  value('verbose', options.verbose);
  value('extensions', options.extensions);
  value('parser', options.parser);
  for (const pattern of [].concat(options.ignorePattern || [], options.ignoreSet || [])) value('ignore-pattern', pattern);
  for (const config of [].concat(options.ignoreConfig || [])) value('ignore-config', config);
  for (const [name, enabled] of [['dry', options.dry], ['print', options.print], ['babel', options.babel !== false], ['gitignore', options.gitignore], ['run-in-band', options.runInBand], ['silent', options.silent], ['fail-on-error', options.failOnError]]) {
    result.push(`--${enabled ? '' : 'no-'}${name}`);
  }
  for (const [name, current] of Object.entries(options)) {
    if (known.has(name) || current == null || current === false) continue;
    for (const item of Array.isArray(current) ? current : [current]) result.push(`--${name}=${typeof item === 'string' ? item : JSON.stringify(item)}`);
  }
  return result;
}

exports.run = function run(transform, paths, options = {}) {
  const root = path.resolve(__dirname, '..');
  const resultFile = path.join(os.tmpdir(), `jscodeshift-result-${process.pid}-${Date.now()}.json`);
  const executable = binary(root);
  const args = executable.prefix.concat([`--transform=${transform}`, ...optionArgs(options), ...paths.map(String)]);
  return new Promise((resolve, reject) => {
    const child = spawn(executable.command, args, {
      cwd: process.cwd(), stdio: 'inherit',
      env: {...process.env, JSCODESHIFT_ROOT: root, JSCODESHIFT_RESULT_FILE: resultFile},
    });
    child.on('error', reject);
    child.on('exit', code => {
      try {
        if (fs.existsSync(resultFile)) {
          const result = JSON.parse(fs.readFileSync(resultFile, 'utf8'));
          fs.unlinkSync(resultFile);
          resolve(result);
        } else if (code === 0) resolve([]);
        else reject(Object.assign(new Error(`jscodeshift exited with code ${code}`), {exitCode: code}));
      } catch (error) { reject(error); }
    });
  });
};
