    abbr: Option<char>,
    full: &'a str,
    flag: bool,
    choices: Option<&'a str>,
    metavar: Option<&'a str>,
    list: bool,
    help: &'a str,
    default: Option<&'a str>,
}

fn format_option(option: &HelpOption<'_>) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = option.abbr { text.push_str(&format!("-{abbr}, ")); } else { text.push_str("    "); }
    text.push_str("--");
    if option.flag { text.push_str("(no-)"); }
    text.push_str(option.full);
    if let Some(choices) = option.choices { text.push('='); text.push_str(choices); }
    else if let Some(metavar) = option.metavar { text.push('='); text.push_str(metavar); }
    if option.list { text.push_str(" ..."); }
    if option.default.is_some() || !option.help.is_empty() {
        text.push_str("  ");
        if text.len() < 32 { text.push_str(&" ".repeat(32 - text.len())); }
        let text_length = text.len();
        text.push_str(option.help);
        if let Some(default) = option.default {
            if !option.help.is_empty() { text.push('\n'); }
            text.push_str(&" ".repeat(text_length));
            text.push_str(&format!("(default: {default})"));
        }
    }
    text
}

