pub fn enabled() -> bool {
    let environment = |name: &str| std::env::var(name).is_ok_and(|value| !value.is_empty());
    let arguments: Vec<_> = std::env::args().collect();
    !environment("NO_COLOR")
        && (environment("FORCE_COLOR")
            || arguments.iter().any(|argument| argument == "--color")
            || cfg!(windows)
            || (std::io::stdout().is_terminal() && std::env::var("TERM").map_or(true, |term| term != "dumb"))
            || environment("CI"))
}

pub fn foreground(code: u8, value: impl AsRef<str>) -> String {
    if enabled() { format!("\x1b[{code}m{}\x1b[39m", value.as_ref()) } else { value.as_ref().to_owned() }
}

pub fn label(background: u8, value: &str) -> String {
    if enabled() { format!("\x1b[{background}m\x1b[37m{value}\x1b[39m\x1b[49m") } else { value.to_owned() }
}
